() => {
  const cells = Array.from(document.querySelectorAll('td, th'));
  const cell = cells.find(c => c.textContent.trim() === 'MFAMB');
  if (!cell) return 'MFAMB not found';
  const row = cell.closest('tr');
  return row.innerText + '\n---LINK---\n' + (row.querySelector('a') ? row.querySelector('a').href : 'no link');
}

() => {
  // Find the Readability Improvements section header and extract its table rows
  const headers = Array.from(document.querySelectorAll('h2, h3, h4'));
  const target = headers.find(h => h.textContent.includes('Readability'));
  if (!target) return 'no readability section';
  let table = null;
  let el = target.nextElementSibling;
  while (el && !table) {
    if (el.tagName === 'TABLE') table = el;
    el = el.nextElementSibling;
  }
  if (!table) return 'no table found';
  const rows = Array.from(table.querySelectorAll('tr'));
  return rows.map(r => Array.from(r.querySelectorAll('td, th')).map(c => c.textContent.trim()).join(' | ')).join('\n');
}

